nta.declaration:
// ============================================================================
// GLOBAL DECLARATIONS — SUPPLY CHAIN V11.3
// ============================================================================
// Purpose:
//   This declaration block defines the complete shared structure of the
//   UPPAAL SMC supply-chain model. It includes:
//     1. Entity counts and bounded identifier types
//     2. Product bill-of-materials reference
//     3. Disruption and resilience-practice activation switches
//     4. Inventory capacities, safety thresholds, batches, and timings
//     5. Shared stock, demand, sales, and transport state variables
//     6. Disruption, practice, and diagnostic counters
//     7. FIFO request-management functions
//     8. Resilience KPI functions
//     9. Raw-material replenishment and production-support logic
//    10. Synchronization channels
//
// Important:
//   The structure and logic are kept identical to the working version.
//   Only comments, spacing, and section organization were improved.
// ============================================================================


// ============================================================================
// 1. SYSTEM ENTITIES AND IDENTIFIER TYPES
// ============================================================================
// Each entity type uses a bounded integer typedef. These bounded types are used
// as template parameters, array indexes, and function parameters.
// ============================================================================

// ---------- Production units ----------
const int N_PROD = 2;
typedef int[0, N_PROD-1] prod_id;

// ---------- Customers ----------
const int N_CUST = 71;
typedef int[0, N_CUST-1] cust_id;

// ---------- Stores ----------
const int N_STORE = 3;
typedef int[0, N_STORE-1] store_id;

// ---------- Suppliers ----------
const int N_SUPP = 1;
typedef int[0, N_SUPP-1] supp_id;

// ---------- Raw materials ----------
const int N_RM = 5;
typedef int[0, N_RM-1] rm_id;

// ---------- Large bounded integer type ----------
// Used for cumulative counters that can become large during simulation.
typedef int[0, 1000000] big_int;


// ============================================================================
// 2. BILL OF MATERIALS REFERENCE — FINISHED PRODUCT AA-F12
// ============================================================================
// Raw material index meaning:
//   0 = AA-R02 Blueberries
//   1 = AA-R05 Wheat
//   2 = AA-R06 Oats
//   3 = AA-P01 Large Box (1 kg)
//   4 = AA-P02 Large Bag (1 kg)
// ============================================================================


// ============================================================================
// 3. SCENARIO ACTIVATION SWITCHES
// ============================================================================
// Change false/true to activate or deactivate each modeled disruption/practice.
//
// Note:
//    TRACK_PRODUCTION_BLOCKING_KPI is kept because it exists in the working model.
//   In the current declaration logic, production feasibility is still governed by
//   raw-material availability through can_start_production().
// ============================================================================

// ---------- V10 disruption switches ----------
// [DK:DS] Demand shock disruption
const bool ENABLE_D_DEMAND_SHOCK = false;

// [DK:RS] Raw-material shortage disruption
const bool ENABLE_D_RAW_SHORTAGE = false;

// [DK:QS] Quality shock disruption
const bool ENABLE_D_QUALITY_SHOCK = false;

// [DK:FTD] Finished-goods transport delay disruption
const bool ENABLE_D_FINISHED_TRANSPORT_DELAY = false;

// ---------- V11 resilience-practice switches ----------
// [PK:ERR] Emergency raw-material replenishment practice
const bool ENABLE_P_EMERGENCY_RAW_REPLENISHMENT = true;

// [PK:ARSS] Adaptive raw safety stock practice
const bool ENABLE_P_ADAPTIVE_RAW_SAFETY_STOCK = false;

// [PK:DSC] Demand surge capacity practice
const bool ENABLE_P_DEMAND_SURGE_CAPACITY = false;

// [PK:BFGT] Backup finished-goods truck practice
const bool ENABLE_P_BACKUP_FINISHED_GOODS_TRUCK = false;

// ============================================================================
// 4. TRANSPORT ENTITY TYPES
// ============================================================================
// Truck1 handles upstream raw-material transport.
// Truck2 handles downstream finished-product transport from the production /
// warehouse stock to the stores.
// ============================================================================

// ---------- Upstream raw-material trucks ----------
const int N_TRUCK1 = 1;
typedef int[0, N_TRUCK1-1] truck1_id;

// ---------- Downstream finished-product trucks ----------
const int NORMAL_TRUCK2_COUNT = 3;
const int N_TRUCK2 = NORMAL_TRUCK2_COUNT + 1;
typedef int[0, N_TRUCK2-1] truck2_id;

// ============================================================================
// 5. INVENTORY THRESHOLDS, BATCH SIZES, AND TIMING PARAMETERS
// ============================================================================
// This section defines the numerical configuration of the model:
//   - store maximum capacities
//   - store safe-inventory thresholds
//   - finished-product and raw-material safety thresholds
//   - raw-material consumption and replenishment batches
//   - production, shipment, and customer-order quantities
//   - production and transport timing parameters
// ============================================================================

// ---------- Store capacity and store safety levels ----------
const int max_stock[N_STORE]      = {1318, 1438, 1376};
const int safe_inventory[N_STORE] = {210, 300, 200};

// ---------- Finished-product and raw-material safety thresholds ----------
const int safe_done      = 200;
const int safe_raw[N_RM] = {160, 190, 190, 530, 530};

// ---------- Raw-material consumption per production batch ----------
const int RAW_USE_PER_BATCH[N_RM] = {113, 131, 131, 376, 376};

// ---------- Raw-material replenishment batch ----------
const int RAW_BATCH[N_RM] = {133, 256, 278, 775, 775};

// ---------- Finished-product and customer-order batch sizes ----------
const int PROD_BATCH  = 376;
const int SHIP_BATCH  = 83;
const int ORDER_BATCH = 10;

// ---------- Customer order and operation timing ----------
const int ORDER_MIN = 11;

const int PROD_MIN = 1;
const int PROD_MAX = 1;

const int T1_MIN = 8;
const int T1_MAX = 16;

const int T2_MIN = 1;
const int T2_MAX = 1;




const bool TRACK_PRODUCTION_BLOCKING_KPI = true;

// ============================================================================
// V11.4 FINISHED-GOODS TRANSPORT DELAY DISRUPTION
// ============================================================================
// This disruption delays downstream finished-goods transport.
// A delay window occurs once per period, starting at a random offset.
// During the active window, any finished-goods truck trip that starts is delayed.
//
// Interpretation:
//   Normal finished transport duration = T2_MAX = 1 time unit.
//   Disrupted finished transport duration = 10 time units.
//   One delay window occurs every 255 time units.
//   Delay window duration = 50 time units.
// ============================================================================

const int FG_TRANSPORT_DELAY_PERIOD = 255;
const int FG_TRANSPORT_DELAY_DURATION = 50;
const int FG_TRANSPORT_DELAY_TRIP_TIME = 10;

// ============================================================================
// 6. SHARED INVENTORY, DEMAND, SALES, AND TIME STATE
// ============================================================================
// These variables represent the current state of the supply chain during
// simulation: inventories, incoming shipments, pending store requests,
// cumulative demand/sales, and discrete simulation time.
// ============================================================================

// ---------- Store finished-product stock ----------
int[0,1000000] inventory_stock[N_STORE] = {0, 0, 0};

// ---------- Finished products assigned to stores but not yet delivered ----------
int[0,1000000] incoming_inventory[N_STORE] = {0, 0, 0};

// ---------- Finished-product stock at production / warehouse level ----------
int[0,1000000] done_stock = 0;

// ---------- Raw-material stock and incoming raw-material quantities ----------
int[0,1000000] raw_stock[N_RM]    = {266, 512, 556, 1550, 1550};
int[0,1000000] incoming_raw[N_RM] = {0, 0, 0, 0, 0};

// ---------- Store replenishment request status ----------
bool inventory_request_pending[N_STORE] = {false, false, false};

// ---------- Global demand and sales counters ----------
int total_ordered = 0;
int total_sold    = 0;

// ---------- Per-customer order counters ----------
int orders_made[N_CUST];
int orders_received[N_CUST];

// ---------- Discrete simulation time ----------
int sim_time = 0;


// ============================================================================
// 7. SUPPLIER AND RAW-MATERIAL DELIVERY MONITORING
// ============================================================================
// These counters are used to observe the delivered raw-material quantities,
// both globally by supplier and individually by raw-material type.
// ============================================================================

// ---------- Total raw material delivered by supplier ----------
big_int total_raw_from_supplier[N_SUPP] = {0};

// ---------- Total raw material delivered per raw-material type ----------
big_int total_raw_by_material[N_RM] = {0, 0, 0, 0, 0};


// ============================================================================
// 8. TRUCK AVAILABILITY FLAGS
// ============================================================================
// A truck is busy while it is assigned to an ongoing transport operation.
// ============================================================================

bool truck1_busy[N_TRUCK1];
bool truck2_busy[N_TRUCK2];


// ============================================================================
// 9. CUSTOMER ORDER TIMING AND STOCHASTIC DELAY PARAMETERS
// ============================================================================
// Customer inter-order delays are generated with a gamma-based distribution.
// First orders are staggered so that all customers do not order at the same
// initial instant.
// ============================================================================


// ---------- Gamma distribution for customer inter-order delays ----------
const double ORDER_G_SHAPE = 4.0;
const double ORDER_G_SCALE = 0.5;   // Mean extra delay = shape × scale = 2

int[0,400] order_delay[N_CUST];

// ---------- First-order staggering ----------
const int FIRST_ORDER_BASE = 11;
const int FIRST_ORDER_GAP  = 8;

const double FIRST_JIT_SHAPE = 2.0;
const double FIRST_JIT_SCALE = 0.5; // Mean jitter = 1

bool first_order_done[N_CUST];


// ============================================================================
// 10. RAW-MATERIAL QUANTITY DISRUPTION
// ============================================================================
// When enabled, the raw-material shortage mechanism makes the supplier send
// half of the normal raw-material batch for a limited number of events during
// each shortage period.
// ============================================================================

bool current_raw_shipment_is_short = false;

const int RAW_SHORTAGE_PERIOD = 510;
const int RAW_SHORTAGE_EVENTS_PER_PERIOD = 2;

int raw_shortage_remaining = 0;
int total_raw_shortage_events = 0;

int last_raw_shipment_qty[N_RM] = {0, 0, 0, 0, 0};

// ---------- Raw-shortage period diagnostics ----------
int total_raw_shortage_periods = 0;
int last_raw_shortage_period_time = -1;
int last_raw_shortage_time = -1;
bool last_raw_shipment_was_short = false;

// ---------- Customer waiting diagnostics ----------
int wait_obs[N_CUST];
int first_wait_value[N_CUST];
bool first_wait_done[N_CUST];

// ---------- Quality-shock diagnostics ----------
int total_shock_events = 0;
int total_shock_batches = 0;

int last_shock_trigger_time = -1;
int last_defect_pct = 0;

bool last_batch_was_shock = false;

// ---------- Batch-level stockout/recovery diagnostics ----------
int orders_at_empty[N_STORE] = {0, 0, 0};
int served_at_empty[N_STORE] = {0, 0, 0};

int last_recovery_time[N_STORE]  = {-1, -1, -1};
int first_recovery_time[N_STORE] = {-1, -1, -1};
int total_recovery_time[N_STORE] = {0, 0, 0};
int recovery_count[N_STORE]      = {0, 0, 0};

bool recovered_once[N_STORE] = {false, false, false};

// ---------- Safe-stock recovery diagnostics ----------
int total_safe_stock_recovery_time[N_STORE] = {0, 0, 0};
int safe_stock_recovery_count[N_STORE] = {0, 0, 0};

// ============================================================================
// V11.4 FINISHED-GOODS TRANSPORT DELAY STATE AND COUNTERS
// ============================================================================

bool finished_transport_delay_active = false;

int fg_transport_delay_start_offset = 0;

int total_finished_transport_delay_windows = 0;
int last_finished_transport_delay_start = -1;

int total_finished_transport_delayed_trips = 0;
int last_finished_transport_delayed_trip_time = -1;

// Each Truck2 trip stores its own duration at dispatch time.
// This avoids problems if the disruption window ends while a truck is still moving.
int[0,100] t2_trip_duration[N_TRUCK2];

// True if the current/last trip of a truck was affected by the delay.
bool t2_trip_was_delayed[N_TRUCK2];


// ============================================================================
// V11.4 BACKUP FINISHED-GOODS TRUCK PRACTICE STATE AND COUNTERS
// ============================================================================

bool backup_finished_goods_truck_enabled = false;

int total_backup_finished_goods_truck_activations = 0;
int last_backup_finished_goods_truck_activation_time = -1;

// ---------- Random start time for the finished-transport delay window ----------
// The start is clipped so that the 50-unit delay window fits inside the 255-unit period.
// This follows the same style as the existing stochastic disruption timing functions.
int fg_transport_delay_start_sample() {
    int s;

    s = fint(random_gamma(2.0, 60.0));

    if (s > FG_TRANSPORT_DELAY_PERIOD - FG_TRANSPORT_DELAY_DURATION) {
        s = FG_TRANSPORT_DELAY_PERIOD - FG_TRANSPORT_DELAY_DURATION;
    }

    return s;
}

// ---------- Check whether the finished-goods transport delay is currently active ----------
bool finished_transport_delay_currently_active() {
    return ENABLE_D_FINISHED_TRANSPORT_DELAY && finished_transport_delay_active;
}

// ---------- Duration assigned to a new finished-goods transport trip ----------
int current_t2_trip_duration() {
    return finished_transport_delay_currently_active()
           ? FG_TRANSPORT_DELAY_TRIP_TIME
           : T2_MAX;
}

// ---------- Check whether a truck is the backup finished-goods truck ----------
bool is_backup_truck2(truck2_id t) {
    return t >= NORMAL_TRUCK2_COUNT;
}

// ---------- Enable backup finished-goods truck when a delay affects transport ----------
void activate_backup_finished_goods_truck_if_needed() {
    if (ENABLE_P_BACKUP_FINISHED_GOODS_TRUCK
        && finished_transport_delay_currently_active()
        && !backup_finished_goods_truck_enabled) {

        backup_finished_goods_truck_enabled = true;
        total_backup_finished_goods_truck_activations++;
        last_backup_finished_goods_truck_activation_time = sim_time;
    }
}

// ---------- Truck2 availability rule ----------
// Normal trucks are always enabled.
// The backup truck is enabled only after the backup-truck practice is activated.
bool truck2_enabled(truck2_id t) {
    return !is_backup_truck2(t) || backup_finished_goods_truck_enabled;
}

// ---------- Check if at least one enabled Truck2 is available ----------
bool exists_available_enabled_truck2() {
    int t;

    for (t = 0; t < N_TRUCK2; t++) {
        if (truck2_enabled(t) && !truck2_busy[t]) {
            return true;
        }
    }

    return false;
}
// ============================================================================
// 11. V11 PRACTICE KPI COUNTERS
// ============================================================================
// These variables track when the resilience practices are triggered and how
// much additional raw material is added by the emergency replenishment practice.
// ============================================================================

// ---------- Practice 1: emergency raw replenishment ----------
int total_emergency_raw_replenishments = 0;
int last_emergency_raw_replenishment_time = -1;
int total_emergency_raw_added = 0;
bool last_shipment_had_emergency_raw = false;

// ---------- Practice 2: adaptive raw safety stock ----------
int total_adaptive_raw_safety_replenishments = 0;
int last_adaptive_raw_safety_replenishment_time = -1;
bool last_shipment_used_adaptive_raw_safety = false;

// ---------- Practice 3: demand surge capacity ----------
int total_store_parallel_service_activations = 0;
int total_extra_production_line_activations = 0;

int surge_capacity_activation_count() {
    return total_store_parallel_service_activations
         + total_extra_production_line_activations;
}


// ============================================================================
// 12. WAIT OBSERVATION AND FIRST-WAIT TRACKING
// ============================================================================
// Stores the time at which each customer starts waiting. This is used to derive
// first waiting observations and debugging indicators.
// ============================================================================

int wait_start_tick[N_CUST];


// ============================================================================
// 13. GLOBAL PERFORMANCE KPIS
// ============================================================================
// These compact KPI functions are used directly in the verifier query set.
// ============================================================================

// ---------- Customer order-time tracking ----------
int order_time_tick[N_CUST];

// ---------- Total lead time accumulated over served demand ----------
big_int total_lead_time = 0;

// ---------- Global service ratio ----------
// Returns the percentage of ordered units that were served.
int service_ratio_pct() {
    return total_ordered > 0 ? (100 * total_sold) / total_ordered : 0;
}

// ---------- Average customer lead time ----------
// Returns the average delay between customer order and service.
int avg_lead_time() {
    return total_sold > 0 ? total_lead_time / total_sold : 0;
}


// ============================================================================
// 14. PRODUCTION QUALITY DISRUPTION
// ============================================================================
// This section models defective production.
//   - Normal production uses a low gamma-based defect percentage capped at 5%.
//   - During a quality shock, the defect percentage is higher and capped at 25%.
// ============================================================================

// ---------- Quality-shock timing ----------
const int QUALITY_SHOCK_PERIOD = 510;

bool quality_shock_pending = false;

// ---------- Production output counters ----------
int total_broken_products = 0;

big_int total_good_products     = 0;
big_int total_produced_products = 0;

int total_production_batches = 0;

// ---------- Normal defect percentage ----------
int normal_defective_pct() {
    int p;

    p = fint(random_gamma(1.0, 2.0));

    if (p > 5) p = 5;

    return p;
}

// ---------- Shock defect percentage ----------
int shock_defective_pct() {
    int p;

    p = 18 + fint(random_gamma(1.0, 2.0));

    if (p > 25) p = 25;

    return p;
}

// ---------- Defect-rate KPI ----------
// Returns the percentage of produced units that became defective.
int defect_rate_pct() {
    return total_produced_products > 0 ?
           (100 * total_broken_products) / total_produced_products : 0;
}

// ---------- Finish production batch with quality outcome ----------
// Converts one production batch into good units and defective units.
void finish_batch_with_quality() {
    int defect_pct;
    int broken_qty;
    int good_qty;

    if (quality_shock_pending) {
        defect_pct = shock_defective_pct();
        quality_shock_pending = false;
        total_shock_batches++;
        last_batch_was_shock = true;
    } else {
        defect_pct = normal_defective_pct();
        last_batch_was_shock = false;
    }

    broken_qty = (PROD_BATCH * defect_pct) / 100;
    good_qty = PROD_BATCH - broken_qty;

    done_stock += good_qty;
    total_broken_products += broken_qty;
    last_defect_pct = defect_pct;

    total_good_products += good_qty;
    total_produced_products += PROD_BATCH;
    total_production_batches++;
}


// ============================================================================
// 15. REAL PRODUCTION BLOCKED-TIME TRACKING
// ============================================================================
// This section measures explicit production blocking.
//
// Modeling rule:
//   - Production is always physically impossible without enough raw materials.
//   - The switch TRACK_PRODUCTION_BLOCKING_KPI controls whether the explicit
//     BlockedNoRaw state and its KPI counter are activated as a disruption.
//   - Therefore, can_start_production() remains the production-feasibility rule,
//     while should_enter_production_block() is used only for the disruption path.
// ============================================================================

int[-1,1000000] production_block_start[N_PROD] = {-1, -1};
int total_production_blocked_time[N_PROD] = {0, 0};
bool production_blocked[N_PROD] = {false, false};

// Note:
//   The helper function should_enter_production_block() is declared later,
//   after can_start_production(), because UPPAAL requires a function to be
//   defined before it is called inside another declaration function.

// ---------- Open real production block ----------
void open_production_block(prod_id p) {
    if (!production_blocked[p]) {
        production_blocked[p] = true;
        production_block_start[p] = sim_time;
    }
}

// ---------- Close real production block ----------
void close_production_block(prod_id p) {
    if (production_blocked[p]) {
        total_production_blocked_time[p] += sim_time - production_block_start[p];
        production_blocked[p] = false;
        production_block_start[p] = -1;
    }
}

// ---------- Live real production blocked time ----------
// Includes completed explicit-block periods and the active block period, if any.
int production_blocked_time_live(prod_id p) {
    return total_production_blocked_time[p]
         + (production_blocked[p] ? sim_time - production_block_start[p] : 0);
}


// ============================================================================
// 16. LATENT PRODUCTION BLOCKED-TIME TRACKING
// ============================================================================
// Measures hidden production pressure: finished stock is low enough to justify
// production, but production cannot effectively start because raw materials are
// insufficient.
// ============================================================================

bool latent_production_blocked[N_PROD] = {false, false};

int[-1,1000000] latent_production_block_start[N_PROD] = {-1, -1};

int total_latent_production_blocked_time[N_PROD] = {0, 0};
int latent_production_block_count[N_PROD] = {0, 0};
int last_latent_production_block_time[N_PROD] = {0, 0};
int max_latent_production_block_time[N_PROD] = {0, 0};

// ---------- Open latent production block ----------
void open_latent_production_block(prod_id p) {
    if (!latent_production_blocked[p]) {
        latent_production_blocked[p] = true;
        latent_production_block_start[p] = sim_time;
        latent_production_block_count[p]++;
    }
}

// ---------- Close latent production block ----------
void close_latent_production_block(prod_id p) {
    int bt;

    if (latent_production_blocked[p]) {
        bt = sim_time - latent_production_block_start[p];

        last_latent_production_block_time[p] = bt;
        total_latent_production_blocked_time[p] += bt;

        if (bt > max_latent_production_block_time[p]) {
            max_latent_production_block_time[p] = bt;
        }

        latent_production_blocked[p] = false;
        latent_production_block_start[p] = -1;
    }
}

// ---------- Live latent production blocked time ----------
// Includes both completed latent-block periods and the active period, if any.
int latent_production_blocked_time_live(prod_id p) {
    return total_latent_production_blocked_time[p]
         + (latent_production_blocked[p] ? sim_time - latent_production_block_start[p] : 0);
}


// ============================================================================
// 17. STORE REQUEST FIFO MANAGEMENT
// ============================================================================
// Stores send replenishment requests when inventory becomes low. Requests are
// served by Truck2 according to FIFO order.
// ============================================================================

// ---------- Truck-to-store assignment ----------
store_id target_store_of_truck[N_TRUCK2];

// ---------- FIFO request tracking ----------
int store_request_time[N_STORE];
bool store_waiting[N_STORE] = {false, false, false};
int store_order_sequence = 0;

// ---------- Check if any store is waiting ----------
bool exists_store_waiting() {
    int s;

    for (s = 0; s < N_STORE; s++) {
        if (store_waiting[s]) return true;
    }

    return false;
}

// ---------- Get the oldest store request ----------
store_id get_next_store_request() {
    store_id best = 0;
    int min_time = 32767;
    int s;

    for (s = 0; s < N_STORE; s++) {
        if (store_waiting[s] && store_request_time[s] < min_time) {
            min_time = store_request_time[s];
            best = s;
        }
    }

    return best;
}

// ---------- Register a new store replenishment request ----------
void register_store_request(store_id s) {
    if (!store_waiting[s] && !inventory_request_pending[s]) {
        store_request_time[s] = ++store_order_sequence;
        store_waiting[s] = true;
        inventory_request_pending[s] = true;
    }
}

// ---------- Assign the oldest store request to a truck ----------
void dispatch_oldest_store_request(truck2_id t) {
    store_id s = get_next_store_request();

    target_store_of_truck[t] = s;
    store_waiting[s] = false;
    inventory_request_pending[s] = false;
}

// ---------- Check whether the oldest waiting store can be shipped ----------
bool can_ship_oldest_store() {
    store_id s;

    if (!exists_store_waiting())
        return false;

    s = get_next_store_request();

    return done_stock >= SHIP_BATCH &&
           (inventory_stock[s] + incoming_inventory[s] + SHIP_BATCH) <= max_stock[s];
}


// ============================================================================
// 18. CUSTOMER REQUEST FIFO MANAGEMENT
// ============================================================================
// Customer orders are tracked in FIFO order. Store templates then serve the
// oldest waiting customer assigned to their store.
// ============================================================================

int order_sequence = 0;
int request_time[N_CUST];
bool customer_waiting[N_CUST];


// ============================================================================
// 19. CUSTOMER-TO-STORE MAPPING
// ============================================================================
// The 71 customers are divided across the three stores.
// ============================================================================

// ---------- Customer store assignment ----------
store_id cust_store(cust_id c) {
    if (c < 21) return 0;   // Store 0: customers 0..20
    if (c < 51) return 1;   // Store 1: customers 21..50
    return 2;               // Store 2: customers 51..70
}

// ---------- Customer rank inside assigned store ----------
int rank_in_store(cust_id c) {
    if (c < 21) return c;
    if (c < 51) return c - 21;
    return c - 51;
}


// ============================================================================
// 20. STORE-SPECIFIC CUSTOMER WAITING SEARCH
// ============================================================================
// These helpers find whether a store has waiting customers and select the oldest
// waiting customer assigned to that store.
// ============================================================================

// ---------- Check if a store has waiting customers ----------
bool exists_waiting_for_store(store_id s) {
    int i;

    for (i = 0; i < N_CUST; i++) {
        if (customer_waiting[i] && cust_store(i) == s) return true;
    }

    return false;
}

// ---------- Select the oldest waiting customer for a store ----------
cust_id get_next_customer_for_store(store_id s) {
    cust_id best_i = 0;
    int min_time = 32767;
    int i;

    for (i = 0; i < N_CUST; i++) {
        if (customer_waiting[i] &&
            cust_store(i) == s &&
            request_time[i] < min_time) {
            min_time = request_time[i];
            best_i = i;
        }
    }

    return best_i;
}


// ============================================================================
// 21. STORE-LEVEL SERVICE, STOCKOUT, AND RECOVERY KPIS
// ============================================================================
// This section measures local store resilience:
//   - ordered and sold quantities by store
//   - first stockout observation
//   - batch-level stockout state and duration
//   - batch-level recovery time
//   - store availability percentage
// ============================================================================

// ---------- Per-store service counters ----------
int total_ordered_store[N_STORE] = {0, 0, 0};
int total_sold_store[N_STORE]    = {0, 0, 0};

// ---------- First stockout observation ----------
int t_at_empty[N_STORE] = {-1, -1, -1};

// ---------- Batch-level stockout state ----------
int stockout_start_time[N_STORE]     = {-1, -1, -1};
int total_stockout_duration[N_STORE] = {0, 0, 0};
bool in_stockout[N_STORE]            = {false, false, false};

int stockout_count[N_STORE]        = {0, 0, 0};
int stockout_required_qty[N_STORE] = {0, 0, 0};

// ---------- Batch-level recovery metrics ----------
int max_recovery_time[N_STORE] = {0, 0, 0};

// ---------- Open batch-level stockout ----------
// A store enters stockout when its inventory becomes lower than the required
// customer order quantity.
void open_stockout_if_needed(store_id s, int required_qty) {
    if (inventory_stock[s] < required_qty) {

        if (!in_stockout[s]) {
            in_stockout[s] = true;
            stockout_start_time[s] = sim_time;
            stockout_required_qty[s] = required_qty;
            stockout_count[s]++;

            if (t_at_empty[s] < 0) {
                t_at_empty[s] = sim_time;
                orders_at_empty[s] = total_ordered_store[s];
                served_at_empty[s] = total_sold_store[s];
            }
        }
        else {
            if (required_qty > stockout_required_qty[s]) {
                stockout_required_qty[s] = required_qty;
            }
        }
    }
}

// ---------- Close batch-level stockout ----------
// Batch-level recovery occurs when inventory is again sufficient to satisfy the
// required customer order quantity.
void close_stockout_if_needed(store_id s) {
    if (inventory_stock[s] >= stockout_required_qty[s] && in_stockout[s]) {
        int rt;

        rt = sim_time - stockout_start_time[s];

        total_stockout_duration[s] += rt;

        last_recovery_time[s] = rt;
        total_recovery_time[s] += rt;
        recovery_count[s]++;

        if (first_recovery_time[s] < 0)
            first_recovery_time[s] = rt;

        if (rt > max_recovery_time[s])
            max_recovery_time[s] = rt;

        recovered_once[s] = true;
        in_stockout[s] = false;
        stockout_start_time[s] = -1;
        stockout_required_qty[s] = 0;
    }
}

// ---------- Live stockout duration ----------
// Includes both completed stockout time and current stockout time, if active.
int stockout_duration_live(store_id s) {
    return total_stockout_duration[s]
         + (in_stockout[s] ? (sim_time - stockout_start_time[s]) : 0);
}

// ---------- Store availability percentage ----------
// Availability is the percentage of simulated time during which the store is
// not in batch-level stockout.
int availability_pct(store_id s) {
    return sim_time > 0 ?
           100 - (100 * stockout_duration_live(s)) / sim_time : 100;
}


// ============================================================================
// 22. SAFE-STOCK RECOVERY TRACKING
// ============================================================================
// This KPI is stricter than batch-level recovery. It measures how long a store
// needs to return to its safe inventory threshold after falling below it.
// ============================================================================

// ---------- Safe-stock recovery state ----------
bool in_safe_stock_recovery[N_STORE] = {false, false, false};

int[-1,1000000] safe_stock_recovery_start_time[N_STORE] = {-1, -1, -1};

int last_safe_stock_recovery_time[N_STORE] = {0, 0, 0};
int max_safe_stock_recovery_time[N_STORE] = {0, 0, 0};

// ---------- Open safe-stock recovery ----------
void open_safe_stock_recovery_if_needed(store_id s) {
    if (inventory_stock[s] < safe_inventory[s]) {
        if (!in_safe_stock_recovery[s]) {
            in_safe_stock_recovery[s] = true;
            safe_stock_recovery_start_time[s] = sim_time;
        }
    }
}

// ---------- Close safe-stock recovery ----------
void close_safe_stock_recovery_if_needed(store_id s) {
    int rt;

    if (in_safe_stock_recovery[s] && inventory_stock[s] >= safe_inventory[s]) {
        rt = sim_time - safe_stock_recovery_start_time[s];

        last_safe_stock_recovery_time[s] = rt;
        total_safe_stock_recovery_time[s] += rt;
        safe_stock_recovery_count[s]++;

        if (rt > max_safe_stock_recovery_time[s]) {
            max_safe_stock_recovery_time[s] = rt;
        }

        in_safe_stock_recovery[s] = false;
        safe_stock_recovery_start_time[s] = -1;
    }
}

// ---------- Store stock update after serving a customer ----------
// Updates store inventory and activates the corresponding stockout/recovery
// trackers if the stock level becomes critical.
void update_stock_and_track(store_id s, int qty) {
    inventory_stock[s] -= qty;

    open_stockout_if_needed(s, qty);
    open_safe_stock_recovery_if_needed(s);
}


// ============================================================================
// 23. V11.2 COMPACT RESILIENCE KPI AGGREGATION FUNCTIONS
// ============================================================================
// These functions reduce the number of verifier queries by combining store-level
// KPIs into global worst-case resilience indicators.
// ============================================================================

// ---------- Worst store availability across all stores ----------
int min_availability_pct_all() {
    int best;

    best = availability_pct(0);

    if (availability_pct(1) < best) {
        best = availability_pct(1);
    }

    if (availability_pct(2) < best) {
        best = availability_pct(2);
    }

    return best;
}

// ---------- Maximum live stockout duration across all stores ----------
int max_stockout_duration_live_all() {
    int worst;

    worst = stockout_duration_live(0);

    if (stockout_duration_live(1) > worst) {
        worst = stockout_duration_live(1);
    }

    if (stockout_duration_live(2) > worst) {
        worst = stockout_duration_live(2);
    }

    return worst;
}

// ---------- Live safe-stock recovery time for one store ----------
// Returns the maximum observed safe-stock recovery time, including the active
// recovery period if the store is still recovering.
int safe_stock_recovery_time_live(store_id s) {
    int v;

    v = max_safe_stock_recovery_time[s];

    if (in_safe_stock_recovery[s]) {
        if (sim_time - safe_stock_recovery_start_time[s] > v) {
            v = sim_time - safe_stock_recovery_start_time[s];
        }
    }

    return v;
}

// ---------- Maximum live safe-stock recovery time across all stores ----------
int max_safe_stock_recovery_time_live_all() {
    int worst;

    worst = safe_stock_recovery_time_live(0);

    if (safe_stock_recovery_time_live(1) > worst) {
        worst = safe_stock_recovery_time_live(1);
    }

    if (safe_stock_recovery_time_live(2) > worst) {
        worst = safe_stock_recovery_time_live(2);
    }

    return worst;
}


// ============================================================================
// 24. RAW-MATERIAL REPLENISHMENT LOGIC
// ============================================================================
// This section detects low raw-material levels, reserves incoming raw-material
// bundles, delivers them, and consumes raw materials for production.
// ============================================================================

// ---------- Emergency raw-material replenishment trigger ----------
// This practice targets raw material 0, AA-R02 Blueberries, because it is the
// limiting raw material in the current model configuration.
bool emergency_raw_replenishment_needed() {
    int m;
    bool missing_raw;

    missing_raw = false;

    for (m = 0; m < N_RM; m++) {
        if (raw_stock[m] < RAW_USE_PER_BATCH[m]) {
            missing_raw = true;
        }
    }

    return ENABLE_P_EMERGENCY_RAW_REPLENISHMENT
        && (
            (raw_stock[0] + incoming_raw[0]) < (2 * RAW_USE_PER_BATCH[0])
            ||
            (done_stock < safe_done + PROD_BATCH && missing_raw)
        );
}

// ---------- Effective raw-material safety threshold ----------
// Resilience practices can raise the trigger threshold for raw material 0.
int effective_safe_raw(rm_id m) {
    int target;

    target = safe_raw[m];

    // Practice 1: emergency replenishment creates a moderate earlier trigger.
    if (ENABLE_P_EMERGENCY_RAW_REPLENISHMENT && m == 0) {
        if (safe_raw[m] + RAW_USE_PER_BATCH[m] > target) {
            target = safe_raw[m] + RAW_USE_PER_BATCH[m];
        }
    }

    // Practice 2: adaptive safety stock creates a stronger preventive trigger.
    if (ENABLE_P_ADAPTIVE_RAW_SAFETY_STOCK && m == 0) {
        if (safe_raw[m] + 2 * RAW_USE_PER_BATCH[m] > target) {
            target = safe_raw[m] + 2 * RAW_USE_PER_BATCH[m];
        }
    }

    return target;
}

// ---------- Check if one raw material is below its effective threshold ----------
bool raw_below_threshold(rm_id m) {
    return (raw_stock[m] + incoming_raw[m]) < effective_safe_raw(m);
}

// ---------- Detect adaptive raw safety-stock usage ----------
// True only when raw material 0 is below the adaptive threshold but not yet below
// the original V10 threshold.
bool adaptive_raw_safety_used() {
    return ENABLE_P_ADAPTIVE_RAW_SAFETY_STOCK
        && (raw_stock[0] + incoming_raw[0] < effective_safe_raw(0))
        && (raw_stock[0] + incoming_raw[0] >= safe_raw[0]);
}

// ---------- Check if any raw material needs replenishment ----------
bool exists_bundle_replenishment() {
    int m;

    for (m = 0; m < N_RM; m++) {
        if (raw_below_threshold(m)) return true;
    }

    return false;
}

// ---------- Reserve a complete raw-material bundle ----------
// If the raw-shortage disruption is active, the reserved quantities are reduced.
// If resilience practices are active, raw material 0 can receive additional or
// earlier replenishment.
void reserve_raw_bundle() {
    int m;
    int q;
    bool use_emergency_raw;
    bool use_adaptive_raw_safety;

    current_raw_shipment_is_short = ENABLE_D_RAW_SHORTAGE && raw_shortage_remaining > 0;
    use_emergency_raw = emergency_raw_replenishment_needed();
    use_adaptive_raw_safety = adaptive_raw_safety_used();

    for (m = 0; m < N_RM; m++) {
        if (current_raw_shipment_is_short) {
            q = RAW_BATCH[m] / 2;
        } else {
            q = RAW_BATCH[m];
        }

        // Emergency top-up for the bottleneck raw material:
        // 0 = AA-R02 Blueberries.
        if (use_emergency_raw && m == 0) {
            q += RAW_USE_PER_BATCH[0];
        }

        incoming_raw[m] += q;
        last_raw_shipment_qty[m] = q;
    }

    if (use_emergency_raw) {
        total_emergency_raw_replenishments++;
        last_emergency_raw_replenishment_time = sim_time;
        total_emergency_raw_added += RAW_USE_PER_BATCH[0];
        last_shipment_had_emergency_raw = true;
    } else {
        last_shipment_had_emergency_raw = false;
    }

    if (use_adaptive_raw_safety) {
        total_adaptive_raw_safety_replenishments++;
        last_adaptive_raw_safety_replenishment_time = sim_time;
        last_shipment_used_adaptive_raw_safety = true;
    } else {
        last_shipment_used_adaptive_raw_safety = false;
    }

    if (current_raw_shipment_is_short) {
        raw_shortage_remaining--;
    }
}

// ---------- Deliver a complete raw-material bundle ----------
// Transfers the last reserved quantities from incoming_raw[] to raw_stock[].
void deliver_raw_bundle() {
    int m;
    int q;
    int total_q = 0;

    for (m = 0; m < N_RM; m++) {
        q = last_raw_shipment_qty[m];

        raw_stock[m] += q;
        incoming_raw[m] -= q;
        total_raw_by_material[m] += q;

        total_q += q;
    }

    total_raw_from_supplier[0] += total_q;

    if (current_raw_shipment_is_short) {
        total_raw_shortage_events++;
        last_raw_shortage_time = sim_time;
        last_raw_shipment_was_short = true;
    } else {
        last_raw_shipment_was_short = false;
    }
}

// ---------- Check if enough raw materials exist for one production batch ----------
bool has_all_materials_for_batch() {
    int m;

    for (m = 0; m < N_RM; m++) {
        if (raw_stock[m] < RAW_USE_PER_BATCH[m]) return false;
    }

    return true;
}

// ---------- Production feasibility condition ----------
bool can_start_production() {
    return has_all_materials_for_batch();
}

// ---------- Production-blocking activation ----------
// Returns true only when the production-blocking disruption is activated.
bool production_blocking_enabled() {
    return TRACK_PRODUCTION_BLOCKING_KPI;
}

// ---------- Explicit production-blocking condition ----------
// This function should be used on transitions that enter BlockedNoRaw.
bool should_enter_production_block() {
    return production_blocking_enabled() && !can_start_production();
}

// ---------- Consume raw materials for one production batch ----------
void consume_materials_for_batch() {
    int m;

    if (has_all_materials_for_batch()) {
        for (m = 0; m < N_RM; m++) {
            raw_stock[m] -= RAW_USE_PER_BATCH[m];
        }
    }
}


// ============================================================================
// 25. PRODUCTION REQUEST FLAGS
// ============================================================================
// Indicates whether a production request has already been sent and is waiting
// to be completed.
// ============================================================================

bool production_request_pending[N_PROD] = {false, false};


// ============================================================================
// 26. DEMAND SHOCK MECHANISM
// ============================================================================
// Models a high-demand window. During the shock, order delays are reduced and
// customer order quantities can increase.
// ============================================================================

// ---------- Demand-shock timing ----------
const int DEMAND_SHOCK_PERIOD = 510;

// ---------- Demand-shock stochastic calibration parameters ----------
// Pulled out as named consts (rather than inline literals inside the sample
// functions below) so they can be read/edited from the GUI's Calibration
// tab for sensitivity analysis, the same way ENABLE_* flags are.
const double DEMAND_SHOCK_PCT_SHAPE = 1.0;
const double DEMAND_SHOCK_PCT_SCALE = 2.0;
const double DEMAND_SHOCK_DURATION_SHAPE = 1.0;
const double DEMAND_SHOCK_DURATION_SCALE = 10.0;

bool demand_shock_active = false;

int demand_shock_pct = 0;          // 5..10%
int demand_shock_duration = 0;     // about 50..70 time units
int demand_shock_start_offset = 0; // random start inside the period

// ---------- Demand-shock counters ----------
int total_demand_shocks = 0;
int last_demand_shock_start = -1;
int shock_orders_made = 0;

// ---------- Customer order quantity ----------
int[0,100] order_qty[N_CUST];

// ---------- Demand-shock percentage sample ----------
int demand_shock_pct_sample() {
    int p;

    p = 5 + fint(random_gamma(DEMAND_SHOCK_PCT_SHAPE, DEMAND_SHOCK_PCT_SCALE));

    if (p > 10) p = 10;

    return p;
}

// ---------- Demand-shock duration sample ----------
int demand_shock_duration_sample() {
    int d;

    d = 50 + fint(random_gamma(DEMAND_SHOCK_DURATION_SHAPE, DEMAND_SHOCK_DURATION_SCALE));

    if (d > 70) d = 70;

    return d;
}

// ---------- Demand-shock start-time sample ----------
// The start is clipped so that the shock window fits inside the period.
int demand_shock_start_sample() {
    int s;

    s = fint(random_gamma(2.0, 250.0));

    if (s > DEMAND_SHOCK_PERIOD - 70)
        s = DEMAND_SHOCK_PERIOD - 70;

    return s;
}

// ---------- Apply demand shock to customer order delay ----------
// During the shock, the delay is reduced, increasing the demand rate.
int apply_demand_shock(int base_delay) {
    int d;

    if (ENABLE_D_DEMAND_SHOCK && demand_shock_active)
        d = base_delay - (base_delay * demand_shock_pct) / 100;
    else
        d = base_delay;

    return d < 1 ? 1 : d;
}



// ---------- Shock order quantity ----------
// During the shock, order quantity is sampled between about 11 and 13.
int shock_order_qty_sample() {
    int q;

    q = 11 + fint(random_gamma(1.0, 1.0));

    if (q > 13) q = 13;

    return q;
}

// ---------- Current customer order quantity ----------
// Uses normal order quantity outside shock and shock quantity during shock.
int current_order_qty_sample() {
    return (ENABLE_D_DEMAND_SHOCK && demand_shock_active) ? shock_order_qty_sample() : ORDER_BATCH;
}

// ---------- Demand surge-capacity practice ----------
// Active only during an actual demand-shock window.
bool surge_capacity_active() {
    return ENABLE_P_DEMAND_SURGE_CAPACITY
        && ENABLE_D_DEMAND_SHOCK
        && demand_shock_active;
}

// ---------- Production-line availability ----------
// Line 0 is the normal line.
// Line 1 is available only during demand-shock surge capacity.
bool production_line_enabled(prod_id p) {
    return p == 0 || surge_capacity_active();
}

// ---------- Check if at least one enabled production line can still receive a request ----------
bool exists_available_enabled_production_line() {
    int i;

    for (i = 0; i < N_PROD; i++) {
        if (production_line_enabled(i) && !production_request_pending[i]) {
            return true;
        }
    }

    return false;
}


int max_production_blocked_time_live_all() {
    int i;
    int worst;

    worst = production_blocked_time_live(0);

    for (i = 1; i < N_PROD; i++) {
        if (production_blocked_time_live(i) > worst) {
            worst = production_blocked_time_live(i);
        }
    }

    return worst;
}

int max_latent_production_blocked_time_live_all() {
    int i;
    int worst;

    worst = latent_production_blocked_time_live(0);

    for (i = 1; i < N_PROD; i++) {
        if (latent_production_blocked_time_live(i) > worst) {
            worst = latent_production_blocked_time_live(i);
        }
    }

    return worst;
}

int max_latent_production_block_time_all() {
    int i;
    int worst;

    worst = max_latent_production_block_time[0];

    for (i = 1; i < N_PROD; i++) {
        if (max_latent_production_block_time[i] > worst) {
            worst = max_latent_production_block_time[i];
        }
    }

    return worst;
}


// ============================================================================
// 27. SYNCHRONIZATION CHANNELS
// ============================================================================
// Broadcast channels synchronize customers, stores, transport, production, and
// raw-material delivery templates.
// ============================================================================

broadcast chan notify_inventory_low[N_STORE];

broadcast chan request_finished_ship[N_TRUCK2];
broadcast chan finished_delivered[N_TRUCK2];

broadcast chan customer_ordered[N_CUST];
broadcast chan customer_served[N_CUST];

broadcast chan request_production[N_PROD];
broadcast chan production_done[N_PROD];

broadcast chan request_raw_material[N_TRUCK1];
broadcast chan raw_delivered;

template.declaration:
// Place local declarations here.
clock c;
clock w;
